def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    # Validate input
    if nanoseconds is None:
        return None
    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise TypeError(f"'nanoseconds' must be an integer representing nanoseconds: {exc}") from exc

    # Normalize nanoseconds to a single day
    ns_per_day = 86400 * 10**9
    ns = ns % ns_per_day

    seconds, rem_ns = divmod(ns, 10**9)
    hour, remainder = divmod(seconds, 3600)
    minute, second = divmod(remainder, 60)
    microsecond = rem_ns // 1000  # convert remaining ns to microseconds

    try:
        if tz is None:
            # Local time without timezone
            return datetime.time(hour, minute, second, microsecond)
        else:
            # Time with timezone information
            return datetime.time(hour, minute, second, microsecond, tzinfo=tz)
    except Exception as exc:
        raise ValueError(f"Failed to construct time from nanoseconds {nanoseconds} with tz={tz}: {exc}") from exc

def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since the Unix epoch.
    :param tz: Optional timezone (`datetime.tzinfo`). If None, the local system
               timezone is used. If a timezone is supplied, the nanoseconds are
               interpreted as UTC and converted to the provided timezone.
    :return: :class:`datetime.time` instance representing the point in time.
    """
    # Validate and convert nanoseconds to a float number of seconds
    try:
        ns = float(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be convertible to a float") from exc

    seconds = ns / 1_000_000_000.0

    try:
        if tz is None:
            # Interpret the timestamp in the local timezone
            dt = datetime.datetime.fromtimestamp(seconds)
            return dt.time()
        else:
            # Ensure tz is a tzinfo instance
            if not isinstance(tz, datetime.tzinfo):
                raise TypeError("tz must be a datetime.tzinfo instance")
            # Interpret the timestamp as UTC, then convert to desired tz
            dt_utc = datetime.datetime.utcfromtimestamp(seconds).replace(
                tzinfo=datetime.timezone.utc
            )
            dt_tz = dt_utc.astimezone(tz)
            return dt_tz.time()
    except Exception as e:
        raise ValueError(f"Error converting nanoseconds to time: {e}") from e

