def unit_of_work(metadata=None, timeout=None):
    """
    This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # The wrapped function must receive a transaction as its first argument
            if not args:
                raise TypeError("Transaction function requires a transaction as the first argument")
            tx = args[0]
            # Validate timeout argument
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a number or None")
                if timeout < 0:
                    raise ValueError("timeout must be non-negative")
            # Try to set metadata and timeout on the transaction if the object supports it
            try:
                # If the transaction object has a `config` attribute (common in Neo4j drivers)
                if hasattr(tx, 'config'):
                    config = tx.config.copy() if isinstance(tx.config, dict) else {}
                    if metadata is not None:
                        config['metadata'] = metadata
                    if timeout is not None:
                        config['timeout'] = timeout
                    # Update the config
                    tx.config = config
                # Fallback: some transaction objects expose a `_config` dict
                elif hasattr(tx, '_config') and isinstance(tx._config, dict):
                    if metadata is not None:
                        tx._config['metadata'] = metadata
                    if timeout is not None:
                        tx._config['timeout'] = timeout
            except Exception:
                # Ignore any issues while setting config – the transaction may not support it
                pass
            # Call the original function with the transaction and remaining arguments
            return func(*args, **kwargs)
        return wrapper
    return decorator

