def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration
        function). Dehydration functions receive the value of type understood
        by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate arguments
    if not isinstance(n, int):
        raise TypeError(f"'n' must be an int, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"'qid' must be an int, got {type(qid).__name__}")
    dehydration_hooks = dehydration_hooks or {}
    hydration_hooks = hydration_hooks or {}
    if not isinstance(dehydration_hooks, dict):
        raise TypeError(
            f"'dehydration_hooks' must be a dict, got {type(dehydration_hooks).__name__}"
        )
    if not isinstance(hydration_hooks, dict):
        raise TypeError(
            f"'hydration_hooks' must be a dict, got {type(hydration_hooks).__name__}"
        )

    # Assemble the DISCARD message payload
    discard_msg = {
        "type": "DISCARD",
        "n": n,
        "qid": qid,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
    }

    # Append to the output queue atomically if possible
    try:
        # Prefer non-blocking put to avoid deadlock in producer-consumer setups
        if hasattr(self, "_out_queue"):
            put_method = getattr(self._out_queue, "put_nowait", None)
            if put_method is not None:
                put_method(discard_msg)
            else:
                self._out_queue.put(discard_msg)
        else:
            # If no queue is configured, raise a clear error
            raise RuntimeError("No output queue configured for DISCARD operation")
    except Exception as exc:
        # Wrap any queue-related issue in a runtime error to keep API consistent
        raise RuntimeError(f"Failed to enqueue DISCARD message: {exc}") from exc

    # Return a Response object populated with provided handlers
    # (The Response class should be defined elsewhere in the package)
    try:
        return Response(**handlers)
    except Exception as exc:
        # If handlers can't be passed to Response, return a default Response
        return Response()

