def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence of strings."""
    if seq is None:
        return []
    # Verify that seq is a sequence and contains only strings
    try:
        it = iter(seq)
    except TypeError:
        raise TypeError("seq must be a sequence")
    for item in seq:
        if not isinstance(item, str):
            raise TypeError("sequence items must be strings")
    # Compute a deterministic seed based on sequence content
    seed = 0
    for s in seq:
        for ch in s:
            seed = (seed * 31 + ord(ch)) & 0xFFFFFFFFFFFFFFFF
    # Shuffle using a Random instance seeded with the computed value
    rand = random.Random(seed)
    lst = list(seq)
    rand.shuffle(lst)
    return lst

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence and return a new list."""
    if seq is None:
        raise TypeError("seq must not be None")
    try:
        items = list(seq)
    except Exception as exc:
        raise TypeError("seq must be an iterable sequence of strings") from exc
    if not all(isinstance(item, str) for item in items):
        raise TypeError("all elements of seq must be strings")
    import random as _random
    rnd = _random.Random(0)  # fixed seed for determinism
    shuffled = items[:]
    rnd.shuffle(shuffled)
    return shuffled

