def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    import re
    # Strip whitespace and split on dots
    parts = s.strip().split(".")
    nums: list[int] = []
    for part in parts:
        if part.isdigit():
            nums.append(int(part))
        else:
            # Extract leading digits, e.g., "1rc2" -> 1
            m = re.match(r"^(\d+)", part)
            if m:
                nums.append(int(m.group(1)))
            else:
                # No numeric component; skip this part
                continue
    if not nums:
        raise ValueError(f"Unable to parse version string: {s!r}")
    return tuple(nums)

