def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys

    if not isinstance(cmd, (list, tuple)):
        raise TypeError('cmd must be a sequence')
    if not cmd:
        return tuple()

    # On Windows, use the python executable to run .py files explicitly.
    first = cmd[0]
    if os.name == 'nt' and isinstance(first, str) and first.lower().endswith('.py'):
        # If the script does not exist, try to add a leading quote if needed
        if not os.path.exists(first):
            # Try a relative path by searching in PATH
            found = None
            for p in os.environ.get('PATH', '').split(os.pathsep):
                candidate = os.path.join(p, first)
                if os.path.exists(candidate):
                    found = candidate
                    break
            if found:
                first = found
        return (sys.executable, first) + cmd[1:]

    # Quote any argument that contains whitespace and is not already quoted.
    norm_cmd = []
    for part in cmd:
        if isinstance(part, str) and ' ' in part and not (part.startswith('"') and part.endswith('"')):
            # Don't quote for recognized Windows build numbers or UNC paths
            norm_part = f'"{part}"'
        else:
            norm_part = part
        norm_cmd.append(norm_part)

    return tuple(norm_cmd)

