    if os.name == 'nt':
        # If the first element is a Python script, prepend the interpreter
        first = cmd[0]
        if isinstance(first, str) and first.lower().endswith(('.py', '.pyw')):
            # Avoid double usage if already includes interpreter
            if not first.lower().startswith(sys.executable.lower()):
                new_cmd = (sys.executable, first) + cmd[1:]
