        # Optionally detect shebang in the script file and use sys.executable
        else:
            # Only attempt to read the file if it exists
            if isinstance(first, str) and os.path.isfile(first):
                try:
                    with open(first, 'r', encoding='utf-8', errors='ignore') as f:
                        first_line = f.readline().rstrip('\n')
                    if first_line.startswith('#!'):
                        new_cmd = (sys.executable, first) + cmd[1:]
                        cmd = new_cmd
                except Exception:
                    # Ignore any read errors
                    pass

        # Escape arguments that contain spaces or parentheses (issue 8557)
        escaped_cmd = []
        for arg in cmd:
            if isinstance(arg, str) and (' ' in arg or '(' in arg or ')' in arg):
