@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        if e is None:
            return ''
        exc_type = type(e).__name__
        msg = str(e)

        # Extract traceback frames
        tb = getattr(e, "__traceback__", None)
        if tb is None:
            frames = []
        else:
            frames = traceback.extract_tb(tb)
        # Keep only the last N frames
        if len(frames) > max_level:
            frames = frames[-max_level:]

        parts = [f"{exc_type}: {msg}"]
        for fil, line, func, text in frames:
            # Truncate file path if necessary
            try:
                path_parts = fil.split(os.path.sep)
                if len(path_parts) > max_path_level:
                    fil = os.path.sep.join(['...'] + path_parts[-max_path_level:])
            except Exception:
                pass
            parts.append(f'  File "{fil}", line {line}, in {func}')
            if text:
                parts.append(f'    {text}')

        # Handle chained exceptions
        if getattr(e, "__cause__", None):
            parts.append("Caused by:")
            parts.append(cls.extostr(e.__cause__, max_level, max_path_level))
        elif getattr(e, "__context__", None) and not getattr(e, "__suppress_context__", False):
            parts.append("During handling of the above exception, another exception occurred:")
            parts.append(cls.extostr(e.__context__, max_level, max_path_level))

        return "\n".join(parts)
    except Exception:
        # Fallback in case formatting fails
        return str(e)

