def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError("elements of classes must be types")
        # Determine if this class is a superclass of any other in the list
        is_super = False
        for other in classes:
            if other is cls:
                continue
            try:
                if issubclass(other, cls):
                    is_super = True
                    break
            except TypeError:
                # In case other is not a class; skip it
                continue
        if not is_super:
            result.append(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        seq = list(classes)
    except TypeError:
        raise TypeError("classes argument must be iterable")
    seen = set()
    unique = []
    for c in seq:
        if not isinstance(c, type):
            raise TypeError(f"Non-class object {c!r} in classes")
        if c not in seen:
            seen.add(c)
            unique.append(c)
    result = []
    for i, c in enumerate(unique):
        redundant = False
        for other in unique[i + 1 :]:
            if issubclass(other, c):
                redundant = True
                break
        if not redundant:
            result.append(c)
    return result

