def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    lines = []
    if header is not None:
        if not isinstance(header, str):
            raise TypeError("header must be a string if provided")
        lines.append(header)

    # Obtain iterable of points
    try:
        points_iter = getattr(self, 'points', None)
        if points_iter is None:
            points_iter = iter(self)
    except Exception as exc:
        raise RuntimeError("Graph object is not iterable") from exc

    for point in points_iter:
        # A point is expected to be (coord, value) or a tuple where last
        # element is the value and preceding elements are coordinates.
        try:
            coord, value = point
        except Exception:
            # Attempt unpacking with *coords and value
            try:
                *coord, value = point
            except Exception as exc:
                raise ValueError("Point must be a sequence of coordinates followed by a value") from exc

        # Convert coordinates to string, handling multidimensional coordinates
        if isinstance(coord, (list, tuple)):
            coord_parts = map(str, coord)
        else:
            coord_parts = [str(coord)]
        coord_str = separator.join(coord_parts)

        # Convert value to string, handling iterable values
        if isinstance(value, (list, tuple)):
            val_parts = map(str, value)
            val_str = separator.join(val_parts)
        else:
            val_str = str(value)

        line = f"{coord_str}{separator}{val_str}"
        lines.append(line)

    return "\n".join(lines) + ("\n" if lines else "")

