def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # convert bins to array and ensure numeric
    try:
        bins = np.asarray(bins)
    except Exception as exc:
        raise ValueError("bins must be array-like") from exc

    # prepare edges list
    if isinstance(edges, (list, tuple)):
        edges_list = list(edges)
    else:
        # assume a single ndarray or array-like
        edges_list = [np.asarray(edges)]

    # compute widths for each dimension
    widths = [np.diff(e) for e in edges_list]
    if not widths or any(w.size == 0 for w in widths):
        raise ValueError("edges must contain at least one non-empty array")

    # build volume array matching bins shape
    vol = widths[0]
    for w in widths[1:]:
        vol = np.multiply.outer(vol, w)
    try:
        vol = vol.reshape(bins.shape)
    except Exception:
        # If reshape fails, broadcast multiplication might still work
        pass

    # compute integral as sum over bin values times voxel volume
    return np.sum(bins * vol)

