    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Handle trivial invalid inputs
    if seq is None:
        return False

    # Exclude Source objects
    try:
        # If 'Source' has been defined in the current context
        if isinstance(seq, Source):
            return False
    except NameError:
        # No Source defined, ignore this check
        pass

    # If seq itself is a FillRequest, it's valid
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # If FillRequest is not defined, we can't evaluate
        pass

    # Strings and bytes should not be treated as sequences of requests
    if isinstance(seq, (str, bytes)):
        return False

    # Attempt to iterate over seq; return True if any element is a FillRequest
    try:
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest is not defined, skip the test
                continue
    except TypeError:
        # seq is not iterable
        return False

    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if seq is None:
        return False
    # Reject a Source instance
    if isinstance(seq, Source):
        return False
    # Direct FillRequest instance is valid
    if isinstance(seq, FillRequest):
        return True
    # If seq is iterable, check its items
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # Not iterable
        return False
    # No FillRequest found
    return False

