def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")

    # Helper to compare versions numerically
    def _parse_ver(v):
        if isinstance(v, (int, float)):
            return (float(v),)
        try:
            parts = str(v).split(".")
            return tuple(int(p) for p in parts if p.isdigit())
        except Exception:
            return (0,)

    target_ver = _parse_ver(version)

    from collections import defaultdict

    logical_map = defaultdict(set)

    # First pass: seed keys with entries exactly matching the target version
    for entry in inventory:
        try:
            if _parse_ver(entry.get("version")) == target_ver:
                lp = entry.get("logical_path")
                cf = entry.get("content_file")
                if lp is not None and cf is not None:
                    logical_map[lp].add(cf)
        except Exception:
            # skip malformed entry
            continue

    # Second pass: include duplicates from later versions
    for entry in inventory:
        try:
            ln = entry.get("logical_path")
            if ln in logical_map:
                cf = entry.get("content_file")
                if cf is not None:
                    # Only consider later versions
                    if _parse_ver(entry.get("version")) > target_ver:
                        logical_map[ln].add(cf)
        except Exception:
            continue

    return dict(logical_map)

