            if isinstance(key, str):
                file_keys.add(key)
            # If the value itself is a mapping, recurse
            if isinstance(value, dict):
                _extract_from_mapping(value)
            elif isinstance(value, list):
                _extract_from_list(value)

    def _extract_from_list(items):
        for item in items:
            if isinstance(item, dict):
                _extract_from_mapping(item)

    # Case 1: direct mapping
    _extract_from_mapping(fixity)

    # Case 2: nested under a 'files' key
    if 'files' in fixity and isinstance(fixity['files'], dict):
        _extract_from_mapping(fixity['files'])

    # Case 3: optional list under 'checksums'
    if 'checksums' in fixity and isinstance(fixity['checksums'], list):
        _extract_from_list(fixity['checksums'])

    # Validate that every referenced file exists in the manifest
    unknown = file_keys.difference(manifest_files)
    if unknown:
        raise ValueError(f"Fixity references files not present in manifest: {sorted(unknown)}")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure manifest_files is iterable and can be converted to a set
    try:
        manifest_set = set(manifest_files)
    except Exception as exc:
        raise TypeError("manifest_files must be an iterable of filenames") from exc

    # Normalize fixity to a list of fixity entries
    if isinstance(fixity, dict):
        entries = [fixity]
    elif isinstance(fixity, (list, tuple)):
        entries = fixity
    else:
        raise TypeError("fixity must be a dict or an iterable of dicts")

    required_keys = {"file", "hash"}
    allowed_algorithms = {"md5", "sha1", "sha256", "sha512"}

    for i, entry in enumerate(entries, start=1):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry #{i} is not a dict")

        # Check required keys
        missing_keys = required_keys - entry.keys()
        if missing_keys:
            raise ValueError(f"Fixity entry #{i} missing required keys: {', '.join(missing_keys)}")

        file_ref = entry["file"]
        if file_ref not in manifest_set:
            raise ValueError(f"Fixity entry #{i} references file '{file_ref}' not present in the manifest")

        # Optional algorithm check
        algorithm = entry.get("algorithm")
        if algorithm is not None and algorithm.lower() not in allowed_algorithms:
            raise ValueError(f"Fixity entry #{i} has unsupported algorithm '{algorithm}'")

    # If all checks pass, return True for convenience
    return True

