            raise ValueError("Fixity keys must be strings; got %r" % type(key).__name__)

    # Ensure all keys are in the manifest
    for key in fixity:
        if key not in manifest_files:
            raise ValueError("Fixity references unknown file '%s', not present in the manifest" % key)

    # Optionally, check that every manifest file has an entry in the fixity block
    missing_in_fixity = set(manifest_files) - set(fixity.keys())
    if missing_in_fixity:
        raise ValueError("Missing fixity entries for files: %s" % ', '.join(sorted(missing_in_fixity)))

    # Validate values (hashes)
    for key, value in fixity.items():
        if not isinstance(value, str):
            raise ValueError("Fixity value for '%s' must be a string, got %r" % (key, type(value).__name__))

