        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")
        # Ensure 'hashes' entry exists
        if 'hashes' not in fixity:
            raise ValueError("Missing 'hashes' entry in fixity block")
        hashes = fixity['hashes']
        if not isinstance(hashes, dict):
            raise ValueError("'hashes' entry must be a dictionary mapping filenames to checksums")
        # Convert manifest_files to a set for fast lookup
        if manifest_files is None:
            manifest_set = set()
        else:
            try:
                manifest_set = set(manifest_files)
            except TypeError:
                raise ValueError("manifest_files must be an iterable of filenames")
        # Validate referenced files
        for filename, checksum in hashes.items():
            if filename not in manifest_set:
                raise ValueError(f"File '{filename}' referenced in fixity block but not present in manifest")
            if not isinstance(checksum, str) or not checksum:
                raise ValueError(f"Invalid checksum for file '{filename}': must be a non-empty string")
        # Optional: return True on success
        return True

