def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo

    Returns
    -------
    dict
        Dictionary with keys 'prefix', 'type' and 'path' describing the file.
    """
    import os

    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    if not isinstance(file_path, str):
        raise TypeError(f"file_path must be a string, got {type(file_path).__name__}")

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"file not found: {file_path}")

    # Determine file type based on common media extensions
    _, ext = os.path.splitext(file_path)
    ext = ext.lower()
    # Simplistic categorization
    asset_exts = {'.mp4', '.mov', '.avi', '.mkv', '.m4v', '.mpg', '.mpeg', '.wmv', '.flv'}
    rendition_exts = {'.jpg', '.jpeg', '.png', '.gif', '.bmp', '.tiff', '.webp'}

    if ext in asset_exts:
        file_type = 'asset'
    elif ext in rendition_exts:
        file_type = 'rendition'
    else:
        # fallback: probe content for video vs image using file signatures if available
        try:
            with open(file_path, 'rb') as f:
                header = f.read(12)
            if header.startswith(b'\x00\x00\x00'):
                file_type = 'asset'
            elif header.startswith((b'\xff\xd8\xff', b'\x89PNG\r\n', b'GIF8', b'BM', b'II*\x00', b'MM\x00*',
                                    b'RIFF', b'WEBP')):
                file_type = 'rendition'
            else:
                file_type = 'unknown'
        except Exception:
            file_type = 'unknown'

    return {
        'prefix': prefix,
        'type': file_type,
        'path': file_path
    }

