def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not zip_path:
        return {}

    # Prepare storage
    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for zinfo in z.infolist():
                # Skip directories
                if zinfo.is_dir():
                    continue
                filename = zinfo.filename
                basename, _ = os.path.splitext(os.path.basename(filename))
                try:
                    content = z.read(zinfo)
                except Exception:
                    # If any read error, skip this file
                    continue
                # Initialize package entry if not present
                if basename not in packages:
                    packages[basename] = {}
                packages[basename][filename] = content
    except FileNotFoundError:
        # zip file does not exist: return empty dict
        return {}
    except zipfile.BadZipFile:
        # invalid zip file: return empty dict
        return {}
    except Exception:
        # Catch-all for unexpected errors: return what has been collected
        return packages

    return packages

