def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    if hook is None:
        raise ValueError("hook cannot be None")
    def decorator(func):
        if not callable(func):
            raise TypeError(f"Registered handler must be callable, got {type(func).__name__}")
        try:
            # Ensure the registry exists
            registry = getattr(self, "_registry", None)
            if registry is None:
                registry = {}
                setattr(self, "_registry", registry)
            # Register the function under the hook
            registry.setdefault(hook, []).append(func)
        except Exception as exc:
            # Wrap errors during registration for easier debugging
            raise RuntimeError(f"Failed to register handler for hook {hook!r}") from exc
        return func
    return decorator

