def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Check that the object has a root attribute to walk
    if not hasattr(self, 'root'):
        if show_warnings:
            print("No 'root' attribute found; nothing to validate.")
        return 0, 0

    # Counters for total and valid objects
    num_objects = 0
    good_objects = 0

    def _traverse(obj):
        nonlocal num_objects, good_objects

        # Treat containers specially: iterate over their elements
        if isinstance(obj, (list, tuple, set)):
            for item in obj:
                _traverse(item)
            return
        if isinstance(obj, dict):
            for val in obj.values():
                _traverse(val)
            return

        # An individual object – count it
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                # If the object implements a validate method, call it.
                # It should either return a boolean or raise.
                result = getattr(obj, 'validate', lambda: True)()
                if result is not None and not result:
                    is_valid = False
            except Exception as exc:  # pragma: no cover
                is_valid = False
                if show_warnings:
                    print(f"Validation error on {obj!r}: {exc}")

        if check_digests:
            try:
                result = getattr(obj, 'check_digests', lambda: True)()
                if result is not None and not result:
                    is_valid = False
            except Exception as exc:  # pragma: no cover
                is_valid = False
                if show_warnings:
                    print(f"Digest check error on {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

        # Recursively walk any child containers the object may expose
        child_attr = getattr(obj, 'children', None) or getattr(obj, 'sub_objects', None)
        if child_attr is not None:
            _traverse(child_attr)

    try:
