    except RecursionError:  # pragma: no cover
        if show_warnings:
            print("Maximum recursion depth exceeded while walking the hierarchy.")
    except Exception as exc:  # pragma: no cover
        if show_warnings:
            print(f"Error while walking hierarchy: {exc}")

    return num_objects, good_objects

