def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    parts = version.split('.')
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        # If any part is not fully numeric, cannot compute next version
        raise ValueError("Version parts must be integers separated by dots")
    # Increment the last part
    nums[-1] += 1
    # Preserve leading zeros formatting
    new_parts = []
    for orig, new in zip(parts, nums):
        if orig.startswith('0') and len(orig) > 1:
            new_parts.append(str(new).zfill(len(orig)))
        else:
            new_parts.append(str(new))
    return '.'.join(new_parts)

