def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if bug_ids is None:
        return
    # Handle a single bug id or an iterable of ids
    if isinstance(bug_ids, (int, str)):
        ids = [bug_ids]
    else:
        try:
            ids = list(bug_ids)
        except TypeError:
            raise ValueError("bug_ids must be a single id or an iterable of ids")
    # Convert all ids to strings and join with commas
    id_str = ",".join(str(i) for i in ids if i is not None)
    if id_str:
        params["ids"] = id_str
    # For Bugzilla API, the key might also be “id[]”; add as alternate if needed
    if "ids[]" not in params and "id[]" not in params:
        params["ids[]"] = ids
    return params

