def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to
    argparse.ArgumentParser instance, give each requested action's subparser a
    shot at parsing all arguments. This allows common arguments like "--repository"
    to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed
    namespace of arguments, a list of remaining arguments not claimed by any
    subparser).
    """
    # Input validation
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping name to ArgumentParser")
    if not hasattr(unparsed_arguments, '__iter__'):
        raise TypeError("unparsed_arguments must be an iterable of arguments")

    parsed_results = {}
    remaining_per_parser = []

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(list(unparsed_arguments))
        except SystemExit:
            # Parsing failed (e.g., missing required arguments). Treat as no match.
            namespace = None
            remaining = list(unparsed_arguments)
        parsed_results[name] = namespace
        remaining_per_parser.append(remaining)

    # Determine arguments not claimed by any parser: intersection of all remaining lists
    if remaining_per_parser:
        intersection_set = set(remaining_per_parser[0])
        for rem in remaining_per_parser[1:]:
            intersection_set &= set(rem)

