        except Exception:
            # On error, treat as if no arguments were parsed by this subparser
            namespace = argparse.Namespace()
            unknown = list(unparsed_arguments)
        parsed_dict[name] = namespace

        # Determine which arguments were consumed by this parser
        consumed = set(arg for arg in unparsed_arguments if arg not in unknown)
        all_consumed.update(consumed)

    # Remaining arguments are those not claimed by any subparser
    remaining = [arg for arg in unparsed_arguments if arg not in all_consumed]
    return parsed_dict, remaining

