def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting borgmatic's command-line argument parsers.
    '''
    import click
    try:
        from borgmatic.cli.main import main as borgmatic_main
    except Exception as exc:
        return f'# Error importing borgmatic CLI: {exc}'

    try:
        completion_info = click.shell_completion.get_completion_info(
            borgmatic_main, shell_type='bash', env={}
        )
    except Exception as exc:
        return f'# Error generating completion info: {exc}'

    try:
        script = click.shell_completion.generate_completion_script(completion_info)
    except Exception as exc:
