def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    # Ensure url_args is a dict
    if not isinstance(url_args, dict):
        try:
            url_args = dict(url_args)
        except Exception:
            url_args = {}

    try:
        import re
        # Pattern matches {key} placeholders
        pattern = re.compile(r'\{([a-zA-Z0-9_]+)\}')

        def _replace_match(match):
            key = match.group(1)
            if key in url_args:
                value = url_args[key]
                return str(value)
            # If key not found, keep original placeholder
            return match.group(0)

        replaced_url = pattern.sub(_replace_match, url)
        return replaced_url
    except Exception:
        # In case of unexpected errors, return the original URL unchanged
        return url

def _replace_url_args(url, url_args):
