        pattern = re.compile(r"\{([a-zA-Z0-9_]+)\}")

        def repl(match):
            key = match.group(1)
            # Preserve original placeholder if key not found
            return str(url_args.get(key, match.group(0)))

        return pattern.sub(repl, url)
    except Exception as exception:
        # If any unexpected error occurs, log and return original url
        try:
            logger.warning('Error replacing URL args: %s', exception)
