def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''
    if not url_args:
        return url

    import re
    import urllib.parse

    def _replacer(match: re.Match):
        key = match.group(1)
        if key in url_args:
            val = url_args[key]
            if val is None:
                return ''
            # Encode the value so it is safe for URLs.
            return urllib.parse.quote(str(val), safe='')
        return match.group(0)

    # Replace placeholders like {param} with the corresponding values.
    replaced = re.sub(r'\{([^}]+)\}', _replacer, url)

    # Normalise duplicate slashes (except for the scheme part).
    # e.g., http://example.com//path becomes http://example.com/path
    scheme_split = replaced.split('://', 1)
    if len(scheme_split) == 2:
        scheme, rest = scheme_split
        rest = re.sub(r'/+', '/', rest)
        replaced = scheme + '://' + rest
    else:
        replaced = re.sub(r'/+', '/', replaced)

    return replaced

