    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    import collections

    if not isinstance(flow_params, (dict, list, tuple, set)):
        raise TypeError("flow_params must be a dict, list, tuple, or set")

    def _replace(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for key, val in obj.items():
                # Replace key if it matches register_value
                new_key = key
                if key == register_value:
                    new_key = key  # keep key same; only replace value
                # Replace value if it matches register_value
                if isinstance(val, (dict, list, tuple, set)):
                    new_val = _replace(val)
                else:
                    new_val = register_number if val == register_value else val
                new_dict[new_key] = new_val
            return new_dict
        elif isinstance(obj, list):
            return [_replace(item) for item in obj]
        elif isinstance(obj, tuple):
            return tuple(_replace(item) for item in obj)
        elif isinstance(obj, set):
            return {_replace(item) for item in obj}
        else:
            return register_number if obj == register_value else obj

    return _replace(flow_params)

