def string_to_int(string: str, alphabet: list) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of single-character strings")
    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one character")
    # Ensure alphabet contains unique characters of length 1
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique elements")
    for ch in alphabet:
        if not (isinstance(ch, str) and len(ch) == 1):
            raise ValueError("alphabet must consist of single-character strings")
    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}
