def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Basic input validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        try:
            destination_path = Path(destination_path)
        except Exception as exc:
            raise TypeError("destination_path must be a Path-like object") from exc

    # Ensure the destination directory exists and is empty
    if destination_path.exists():
        if any(destination_path.iterdir()):
            raise FileExistsError(
                f"Destination path {destination_path} already exists and is not empty"
            )
    else:
        try:
            destination_path.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Could not create destination path {destination_path}") from exc

    # Download the archive to a temporary file
    tmp_file_path = None
    try:
        import tempfile
        import os

        with requests.get(url, stream=True, timeout=30) as resp:
            resp.raise_for_status()
            with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp_file:
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:
                        tmp_file.write(chunk)
                tmp_file_path = tmp_file.name
    except Exception as exc:
        raise ConnectionError(f"Unable to download archive from {url}") from exc

    # Extract the archive
    try:
        import tarfile
        import os

        with tarfile.open(tmp_file_path, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError("Failed to extract the downloaded archive") from exc
    finally:
        # Clean up the temporary file regardless of success or failure
        if tmp_file_path and os.path.exists(tmp_file_path):
            try:
                os.unlink(tmp_file_path)
            except OSError:
                pass

    return destination_path

