def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Ensure input is text
    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception:
            s = s.decode('latin1')
    # Resolve platform if needed
    if platform == 'this':
        try:
            import os
            platform = 0 if os.name == 'nt' else 1
        except Exception:
            # Default to POSIX if detection fails
            platform = 1
    # POSIX implementation via shlex
    if platform == 1:
        try:
            import shlex
            return shlex.split(s)
        except Exception as e:
            raise RuntimeError(f"POSIX split failed: {e}") from e
    # Windows implementation using regex
    elif platform == 0:
        # Regex pattern to match Windows cmdline arguments
        pattern = re.compile(r'''
            \s*                                   # optional leading whitespace
            (?:                                   # start of group
              (?:                                   # quoted string
                "(?:\\.|[^"\\])*"                   # double quoted, allow escaped chars
              |
                '(?:\\.|[^'\\])*'                   # single quoted, allow escaped chars
              )
            |
              (?:[^"\s]+)                           # unquoted word
            )
            ''', re.VERBOSE)
        tokens = []
        for match in pattern.finditer(s):
            token = match.group(0).strip()
            if not token:
                continue
            # Strip surrounding quotes if present
            if token[0] in ('"', "'") and token[-1] == token[0]:
                token = token[1:-1]
                # Unescape quoted section
                token = token.replace(r'\"', '"').replace(r"\'", "'")
            # Unescape any escaped space or backslash
            token = token.replace(r'\ ', ' ').replace(r'\\', '\\')
            tokens.append(token)
        return tokens
    else:
        raise ValueError(f"Unsupported platform: {platform}")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex, os, re
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if platform == 'this':
        use_windows = os.name == 'nt'
    elif platform == 1:
        use_windows = False
    elif platform == 0:
        use_windows = True
    else:
        raise ValueError('Unsupported platform')
    if not use_windows:
        return shlex.split(s)
    # Windows splitting
    win_re = re.compile(
        r'''(?:(?<=^)|(?<=\s))(?:"((?:\\.|[^"\\])*?)"|\S+)''',
        re.VERBOSE)
    tokens = []
    for m in win_re.finditer(s):
        quoted = m.group(1)
        if quoted is not None:
            part = quoted
            out = []
            i = 0
            while i < len(part):
                if part[i] == '\\' and i + 1 < len(part):
                    out.append(part[i + 1])
                    i += 2
                else:
                    out.append(part[i])
                    i += 1
            tokens.append(''.join(out))
        else:
            tokens.append(m.group(0))
    return tokens

