def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Ensure the archive exists
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f'Archive not found: {archive_path}')

    # Determine a base name for extraction
    if filename:
        base_name = filename
    else:
        base_name = os.path.splitext(os.path.basename(archive_path))[0]
        # Strip typical double extensions (e.g., .tar.gz, .zip)
        while True:
            root, ext = os.path.splitext(base_name)
            if ext in {'.gz', '.bz2', '.zip'}:
                base_name = root
            else:
                break

    # Create extraction directory
    extract_dir = Path(tmp_path) / base_name
    try:
        extract_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f'Could not create extraction directory {extract_dir}: {exc}')

    # Choose extraction command based on file extension
    if archive_path.endswith(('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar')):
        cmd = ['tar', '-xf', archive_path, '-C', str(extract_dir)]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', archive_path, '-d', str(extract_dir)]
    else:
        raise ValueError(f'Unsupported archive type for file: {archive_path}')

    # Run the extraction
    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f'Extraction failed for {archive_path}: {exc.stderr.decode().strip()}')

    # Return a file URI pointing to the extracted repo
    return f'file://{extract_dir.resolve()}'

