def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        info = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in info:
        # sockaddr might be (address, port) or (address, port, flowinfo, scopeid) for IPv6
        addr = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback: 127.0.0.0/8
            try:
                octets = addr.split('.')
                if len(octets) == 4 and int(octets[0]) == 127:
                    return True
            except ValueError:
                continue
        elif family == socket.AF_INET6:
            # IPv6 loopback: ::1
            if addr == '::1':
                return True
    return False

