    :return: True if the host is the localhost
    """
    # Consider the string literal 'localhost' as a quick check
    if host == 'localhost':
        return True

    try:
        # Resolve the host; ignore port by passing None
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Cannot resolve the host; not considered localhost
        return False
    except Exception:
        # Any other unexpected exception should also return False
        return False

    for family, _, _, _, sockaddr in addrinfo:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            # IPv4 localhost is any address in the 127.0.0.0/8 block
            if ip == '127.0.0.1' or ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # IPv6 localhost is ::1
            if ip == '::1':
                return True

    return False

