def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    if find_paths is None:
        raise ValueError("find_paths cannot be None")
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError(f"find_paths should be an iterable, got {type(find_paths)}")
    transformed = []
    for fragment in iterator:
        if not isinstance(fragment, str):
            raise TypeError(f"Each find_path fragment must be a string, got {type(fragment)}")
        # Preserve fragments that already look like a pattern (contain a colon)
        if ':' in fragment:
            transformed.append(fragment)
        else:
            # Construct a glob that searches for the fragment anywhere in the path
            transformed.append(f'sh:**/*{fragment}*/**')
    return transformed

