def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Try to obtain the variable name and default from the matcher.
    # Many callers use a regex match that may provide named groups 'name' and 'default',
    # or rely on positional groups 1 and 2.
    name = None
    default = None

    # First attempt to use named groups, if available.
    try:
        group_dict = matcher.groupdict()
        if group_dict:
            # use 'name' or any common alternative name for the variable
            name = group_dict.get('name') or group_dict.get('var') or group_dict.get('variable')
            default = group_dict.get('default')
    except AttributeError:
        pass

    # If the name is still missing, fall back to positional groups.
    if name is None:
        try:
            name = matcher.group(1)
        except Exception:
            name = None

    if default is None:
        try:
            default = matcher.group(2)
        except Exception:
            default = None

    if name is None:
        raise ValueError('The matcher does not contain a variable name.')

    # Resolve the value from the environment.
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' not found and no default value provided.")

