def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("image_href must be a non-empty string")
    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Invalid URL: {image_href}") from e
    scheme = parsed.scheme.lower()
    netloc = parsed.netloc
    if not scheme or not netloc:
        raise ValueError(f"URL must contain scheme and netloc: {image_href}")
    use_ssl = scheme == "https"
    # Determine image id from the path.
    path = parsed.path
    if not path:
        raise ValueError(f"No path component in URL: {image_href}")
    # Strip trailing slash and split
    parts = [p for p in path.split('/') if p]
    if not parts:
        raise ValueError(f"No path segments in URL: {image_href}")
    last = parts[-1]
    # Remove query/fragment if any inadvertently present
    last = last.split('?', 1)[0].split('#', 1)[0]
    # Strip file extension if present
    if '.' in last:
        img_id = last.rsplit('.', 1)[0]
    else:
        img_id = last
    if not img_id:
        raise ValueError(f"Could not determine image ID from URL: {image_href}")
    return (img_id, netloc, use_ssl)

