def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern

    :param pattern: a string containing a regex pattern or a compiled regex object
    :param strip: whether to strip leading/trailing whitespace from a string pattern
    :return: re.Pattern object or None if input is None
    :raises TypeError: if the input is not a string or a compiled regex
    :raises ValueError: if the string is not a valid regex pattern
    """
    if pattern is None:
        return None

    # Handle string or bytes pattern
    if isinstance(pattern, (str, bytes)):
        # Strip whitespace if requested
        if strip and isinstance(pattern, str):
            pattern = pattern.strip()
