def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if graph is None:
        raise ValueError("graph argument cannot be None")
    if prop is None:
        raise ValueError("prop argument cannot be None")

    try:
        # Collect all subjects (children) and objects (parents) for the given property
        children = {s for s, p, o in graph.triples((None, prop, None))}
        parents = {o for s, p, o in graph.triples((None, prop, None))}
    except Exception as exc:
        raise ValueError(f"Failed to iterate triples with property {prop}") from exc

    # All nodes that appear anywhere in the hierarchy
    all_nodes = children | parents

    # Roots are those nodes that never appear as a parent (i.e., no incoming edge)
    root_set: Set["Node"] = all_nodes - parents

    # Merge any user supplied root candidates
    if roots:
        root_set.update(roots)

    return root_set

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if graph is None:
        raise ValueError("graph is required and cannot be None")
    try:
        subjects = set()
        objects = set()
        for subj, _p, obj in graph.triples((None, prop, None)):
            # subj is child, obj is parent
            subjects.add(subj)
            objects.add(obj)
        computed_roots = objects - subjects
        if roots is not None:
            # If a subset of roots was provided, intersect to keep only those
            return computed_roots & set(roots)
        return computed_roots
    except Exception as exc:
        # Convert any graph access errors into a more descriptive exception
        raise RuntimeError(
            f"Failed to compute roots for property {prop} in graph: {exc}"
        ) from exc

