def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging

    config_map = {}
    # Use a temporary logger to capture error records
    logger = logging.getLogger('load_configurations')
    class _CaptureHandler(logging.Handler):
        def __init__(self):
            super().__init__(logging.ERROR)
            self.records = []

        def emit(self, record):
            self.records.append(record)

    capture_handler = _CaptureHandler()
    logger.addHandler(capture_handler)
    logger.setLevel(logging.ERROR)

    # Helper to recursively expand environment variables in config objects
    def _expand_env_vars(obj):
        if isinstance(obj, dict):
            return {k: _expand_env_vars(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_expand_env_vars(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    for filepath in config_filenames:
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                raw = f.read()
        except Exception as exc:
            logger.error('Failed to read config file %s: %s', filepath, exc)
            continue

        ext = os.path.splitext(filepath)[1].lower()
        parsed = None

        if ext == '.toml':
            try:
                import toml
            except ImportError as exc:
                logger.error('toml library not available for %s: %s', filepath, exc)
                continue
            try:
                parsed = toml.loads(raw)
            except Exception as exc:
                logger.error('Failed to parse TOML config %s: %s', filepath, exc)
                continue

        elif ext in ('.yaml', '.yml'):
            try:
                import yaml
            except ImportError as exc:
                logger.error('pyyaml library not available for %s: %s', filepath, exc)
                continue
            try:
                parsed = yaml.safe_load(raw)
            except Exception as exc:
                logger.error('Failed to parse YAML config %s: %s', filepath, exc)
                continue

        else:
            logger.error('Unsupported config file extension %s for file %s', ext, filepath)
            continue

        if not isinstance(parsed, dict):
            logger.error('Config file %s did not parse to a dictionary', filepath)
            continue

        # Merge overrides if any
        if overrides and isinstance(overrides, dict):
            merged = {**parsed, **overrides}
        else:
            merged = parsed

        # Resolve environment variables if requested
        if resolve_env:
            try:
                merged = _expand_env_vars(merged)
            except Exception as exc:
                logger.error('Error expanding environment variables in %s: %s', filepath, exc)

