                'levelname': 'ERROR',
                'pathname': filename,
                'msg': f'Error parsing configuration file {filename}: {exc}',
                'args': (),
                'exc_info': (type(exc), exc, exc.__traceback__),
                'func': None,
                'lineno': None,
            })
            error_records.append(record)
            results[filename] = None
            continue

        # Validate that the configuration is a dictionary
        if not isinstance(parsed_config, dict):
            record = logging.makeLogRecord({
                'name': __name__,
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'pathname': filename,
                'msg': f'Configuration file {filename} did not contain a dictionary',
                'args': (),
                'exc_info': None,
                'func': None,
                'lineno': None,
            })
            error_records.append(record)
            results[filename] = None
            continue

        # Resolve environment variables if requested
        if resolve_env:
            parsed_config = _resolve_env_placeholders(parsed_config)

        # Apply overrides if any
        if overrides:
            parsed_config.update(overrides)

        results[filename] = parsed_config

    return results, error_records

