def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Helper to determine if an object is a string (bytes or str)
    def _is_string(x):
        return isinstance(x, (str, bytes))

    # If seq is already a sequence type (list, tuple, bytearray, etc.) but not a string,
    # return it unchanged.
    if isinstance(seq, (list, tuple, bytearray)) and not _is_string(seq):
        seq_type = type(seq).__name__
        return (seq, seq_type)

    # If seq is an iterable but not a sequence type, convert to a list.
    try:
        iter(seq)
    except TypeError:
        # Not iterable; wrap in a list.
        seq_type = 'scalar'
        return ([seq], seq_type)

    # For iterables that aren't lists or tuples (e.g., generators, iterators),
    # consume them into a list. If a buffer size is provided, stop at that size.
    try:
        if bufsize is not None and bufsize >= 0:
            seq_lst = []
            count = 0
            for item in seq:
                seq_lst.append(item)
                count += 1
                if count >= bufsize:
                    break
            seq = seq_lst
        else:
            seq = list(seq)
    except Exception:
        # Fallback: return the original iterable with type 'iterable'
        seq_type = 'iterable'
        return (seq, seq_type)

    seq_type = type(seq).__name__
    return (seq, seq_type)

