def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Determine current scale
    current_scale = getattr(self, 'scale', None)

    # None -> return current scale
    if other is None:
        return current_scale

    # Ensure other is a numeric value
    if not isinstance(other, (int, float)):
        raise TypeError(f"Scale must be a numeric value, got {type(other).__name__}")

    # If current scale unknown or zero, cannot rescale
    if current_scale is None or (isinstance(current_scale, (int, float)) and abs(current_scale) < 1e-12):
        raise LenaValueError("Cannot rescale because current scale is unknown or zero.")

    # Compute scaling factor
    try:
        factor = other / current_scale
    except Exception as exc:
        raise LenaValueError(f"Error computing scaling factor: {exc}") from exc

    # Identify the last coordinate to rescale
    try:
        last_coord = self.coordinates[-1]
    except AttributeError:
        raise AttributeError("Graph does not have a 'coordinates' attribute.")
    except Exception as exc:
        raise AttributeError(f"Could not identify the last coordinate: {exc}") from exc

    # Rescale data and errors if present
    if hasattr(self, 'fields') and isinstance(self.fields, dict):
        if last_coord in self.fields:
            self.fields[last_coord] = self.fields[last_coord] * factor
        else:
            # if field missing, skip
            pass
    else:
        # Fallback: try to access using a single data attribute
        if hasattr(self, last_coord):
            try:
                attr = getattr(self, last_coord)
                setattr(self, last_coord, attr * factor)
            except Exception:
                pass

    # Rescale errors if available
    if hasattr(self, 'errors') and isinstance(self.errors, dict):
        if last_coord in self.errors:
            self.errors[last_coord] = self.errors[last_coord] * factor

    # Update stored scale
    self.scale = other
    return None

