       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    try:
        from zope.interface import Invalid
    except Exception:
        # Fallback if zope.interface is not available
        Invalid = Exception

    errors = []

    # 1. Check that the candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    Invalid(
                        f"Candidate {candidate!r} does not provide interface {iface!r}"
                    )
                )
        except Exception as exc:  # pragma: no cover
            errors.append(
                Invalid(
                    f"Error while checking providedBy for {candidate!r} and {iface!r}: {exc}"
                )
            )

    # 2. Gather interface attributes: methods and non-methods
    iface_attrs = iface.__dict__
    iface_methods = [
        name for name, value in iface_attrs.items() if inspect.isroutine(value)
    ]
    iface_nonmethods = [
        name for name, value in iface_attrs.items() if not inspect.isroutine(value)
    ]

    # Helper to compare signatures reasonably
    def signatures_match(sig_a, sig_b):
        # We consider signatures matching if they have the same number
        # of parameters and the corresponding names/kinds match.
        # Type annotations are compared when both sides provide them.
        a_params = list(sig_a.parameters.values())
        b_params = list(sig_b.parameters.values())
        if len(a_params) != len(b_params):
            return False
        for pa, pb in zip(a_params, b_params):
            if pa.name != pb.name or pa.kind != pb.kind:
                return False
            if pa.annotation is not inspect._empty and pb.annotation is not inspect._empty and pa.annotation != pb.annotation:
