                Invalid(
                    f"Missing required method {name!r} for interface {iface!r}"
                )
            )
            continue
        iface_sig = inspect.signature(iface_attrs[name])
        cand_sig = inspect.signature(getattr(candidate, name))
        if not signatures_match(iface_sig, cand_sig):
            errors.append(
                Invalid(
                    f"Signature mismatch for method {name!r} required by interface {iface!r}"
                )
            )

    # 4. Check attributes
    for name in iface_nonmethods:
        if not hasattr(candidate, name):
            errors.append(
                Invalid(
                    f"Missing required attribute {name!r} for interface {iface!r}"
                )
            )

    # 5. Report errors
    if errors:
        if len(errors) == 1:
            raise errors[0]
        raise Invalid(
            f"Verification failed for interface {iface!r} with {candidate!r}: {errors}"
        )

    return True

