def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is given, it takes precedence
    if explicit_mc is not None:
        return explicit_mc

    # No bases -> default to `type`
    if not bases:
        return type

    def _common_ancestor(a, b):
        """Return the most derived common ancestor of a and b that is a metaclass."""
        # Find the first candidate in a's mro that is also in b's mro
        a_mro = a.mro()
        b_mro = set(b.mro())
        for candidate in a_mro:
            if candidate in b_mro:
                return candidate
        return None

    metaclass = None
    for base in bases:
        try:
            base_meta = type(base)
        except Exception as exc:
            raise TypeError(f"base {base!r} is not a class: {exc}") from exc

        if metaclass is None:
            metaclass = base_meta
            continue

        common = _common_ancestor(metaclass, base_meta)
        if common is None:
            raise TypeError(
                f"metaclass conflict: {metaclass.__name__} (of {bases[0]!r}) "
                f"and {base_meta.__name__} (of {base!r}) are incompatible"
            )
        metaclass = common

    return metaclass

