def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    try:
        if not isinstance(dt, datetime.datetime):
            raise TypeError("dt must be a datetime instance")
        # Ensure UTC representation: if timezone-aware, convert to UTC
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception as e:
        raise ValueError(f"Unable to format datetime: {e}")

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # D* nodes expect UTC timestamps in ISO 8601 format ending with 'Z'
    if dt is None:
        return None
    # Basic type check: should have datetime interface
    if not hasattr(dt, "strftime") or not hasattr(dt, "tzinfo"):
        raise TypeError("Expected a datetime instance with tzinfo support")
    # Convert to UTC
    try:
        utc = getattr(dt, "astimezone")(datetime.timezone.utc)
    except AttributeError:
        # If astimezone or timezone not available, fall back gracefully
        utc = dt
        if not hasattr(dt, "tzinfo") or dt.tzinfo is None:
            try:
                utc = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                pass
    else:
        utc = utc
    # Format to ISO 8601 without fractional seconds
    return utc.strftime("%Y-%m-%dT%H:%M:%SZ")

