def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    tags: Set[str] = set()
    pattern = re.compile(r'(?P<prefix>\B#)(?P<tag>\w+)')
    new_lines = []
    inside_code_block = False

    for line in text.splitlines():
        # Detect markdown code block delimiters
        if '```' in line:
            inside_code_block = not inside_code_block
            new_lines.append(line)
            continue

        if not inside_code_block:
            # Extract tags
            for match in pattern.finditer(line):
                tags.add(match.group('tag'))

            # Replace tags if a replacer is supplied
            if replacer is not None:
                def _repl(m):
                    try:
                        replacement = replacer(m.group('tag'))
                        if replacement is None:
                            # If replacer returns None, keep original
                            return m.group(0)
                        return f"#{replacement}"
                    except Exception:
                        # In case replacer throws, keep original
                        return m.group(0)
                new_line = pattern.sub(_repl, line)
            else:
                new_line = line
        else:
            new_line = line

        new_lines.append(new_line)

    new_text = '\n'.join(new_lines)
    return tags, new_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks. A tag is expected to appear
    as ``# <TAG>`` where ``TAG`` consists of word characters.

    If ``replacer`` is supplied, the tag region is replaced by the string
    returned from ``replacer(tag)``. ``replacer`` must be a callable that
    accepts a single string argument.

    Returns a set of tags and the original or replaced text.
    """
    import re
    from collections import defaultdict

    # Regular expression to match a tag of the form "# <TAG>"
    tag_re = re.compile(r'#\s*<(?P<tag>\w+)>')

    tags: Set[str] = set()
    new_lines = []
    in_code_block = False

    for line in text.splitlines(keepends=True):
        stripped = line.strip()

        # Detect code block fences (can be ```, ```python, etc.)
        if stripped.startswith('```'):
            in_code_block = not in_code_block
            new_lines.append(line)
            continue

        if not in_code_block:
            # Function used by re.sub to process tags
            def _replace(match: re.Match):
                tag_word = match.group('tag')
                tags.add(tag_word)
                if replacer is not None:
                    try:
                        return replacer(tag_word)
                    except Exception:
                        # If replacer fails, keep the original tag
                        return match.group(0)
                return match.group(0)

            try:
                new_line = tag_re.sub(_replace, line)
            except Exception:
                # In case of any regex error, revert to original line
                new_line = line
            new_lines.append(new_line)
        else:
            # Inside a code block – leave the line untouched
            new_lines.append(line)

    new_text = ''.join(new_lines)
    return tags, new_text

