    url_re = re.compile(r'(?:https?://|www\.)[^\s<]+', re.IGNORECASE)
    def replace(match):
        url = match.group(0)
        href = url if url.startswith(('http://', 'https://')) else 'http://' + url
        # Add common link attributes: open in new tab, safeguard
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
    return url_re.sub(replace, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if text is None:
        raise ValueError("Input text cannot be None")
    try:
        import re

        # Regex to find URLs starting with http:// or https://
        url_pattern = re.compile(
            r'\b(?P<url>https?://[^\s<>\]]+)',
            re.IGNORECASE
        )

        # Regex to find lowercase file paths ending in common extensions
        file_pattern = re.compile(
            r'\b(?P<path>[./a-zA-Z0-9_\-\/]+\.(?:py|txt|md|html|css|js|json|xml))\b',
            re.IGNORECASE
        )

        def _make_link(target: str, display: str, attrs: str = ' target="_blank" rel="nofollow"') -> str:
            """Return an anchor element with the given target and display text."""
            return f'<a href="{target}"{attrs}>{display}</a>'

        # First replace URLs
        def replace_url(match):
            url = match.group('url')
            return _make_link(url, url)

        result = url_pattern.sub(replace_url, text)

        # Then replace file paths that are not already linked
        def replace_path(match):
            path = match.group('path')
            # Avoid double-linking if already inside an <a> tag
            if f'href="{path}"' in result:
