    except Exception:
        return None
    if scheme not in ("http", "https", "ftp", "ftps"):
        return None
    headers = {"Host": netloc}
    req = Request(url, headers=headers, method="HEAD")
    try:
        resp = urlopen(req)
        try:
            if hasattr(resp, "code") and resp.code != 200 and scheme not in ("ftp", "ftps"):
