    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.

    Parameters
    ----------
    public_key : str or cryptography public key object
        Path to a PEM encoded public key file, or a preloaded public key
        instance from cryptography.
    doc : str or bytes
        The XML document (optionally including namespaces). String is
        encoded using UTF-8 before verification.
    signature : str or bytes
        The Base64 encoded binary signature or binary signature directly.

    Returns
    -------
    bool
        True if signature is valid for the document, False otherwise.
    """
    # Helper imports
    try:
        import base64
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.hazmat.primitives.serialization import (
            load_pem_public_key,
