def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Keep track of which parsers have already had their includes expanded
    expanded = set()

    def _expand(name, stack):
        # Detect circular includes
        if name in stack:
            cycle = ' -> '.join(stack + [name])
            raise ValueError(f"Circular include detected: {cycle}")
        if name not in parser_dict:
            raise KeyError(f"Included parser '{name}' not found in spec")
        if name in expanded:
            return  # Already expanded, nothing to do

        parser = parser_dict[name]
        if not isinstance(parser, dict):
            # Nothing to expand if not a dict
            expanded.add(name)
            return

        # If there is nothing to include, we can mark as expanded
        if 'include' not in parser:
            expanded.add(name)
            return

