def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Guard against None or non-iterable arguments
    try:
        iterable = iter(args)
    except TypeError:
        return []

    silent = []
    for item in iterable:
        if isinstance(item, str) and item.startswith('-'):
            # Strip all leading '-' characters to get the option name
            name = item.lstrip('-')
            # Skip empty names (possible for a lone '-' or '--')
            if not name:
                continue
            # Preserve order and avoid duplicates
            if name not in silent:
                silent.append(name)
    return silent

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # If args is a Namespace or an object with a 'silent' attribute
    try:
        if hasattr(args, 'silent'):
            silent = getattr(args, 'silent')
            if silent is None:
                return []
            if isinstance(silent, (list, tuple, set)):
                return list(silent)
            # allow comma-separated string
            if isinstance(silent, str):
                return [s.strip() for s in silent.split(',') if s.strip()]
            # fallback: return as single-element list
            return [silent]
        # If args is a dict
        if isinstance(args, dict):
            silent = args.get('silent')
            if silent is None:
                return []
            if isinstance(silent, (list, tuple, set)):
