            if isinstance(silent, str):
                return [s.strip() for s in silent.split(',') if s.strip()]
            return [silent]
        # If args is a list or tuple of string arguments
        if isinstance(args, (list, tuple)):
            silent_args = []
            i = 0
            while i < len(args):
                arg = args[i]
                # Handle flags: --silent or -s
                if arg in ('--silent', '-s'):
                    if i + 1 < len(args):
                        silent_args.append(args[i + 1])
                        i += 1  # skip next element as it's already consumed
                # Handle --silent=VALUE
                elif isinstance(arg, str) and arg.startswith('--silent='):
                    silent_args.append(arg.split('=', 1)[1])
                i += 1
            return silent_args
    except Exception:
        # In case of any unexpected type or error, return empty list
        return []
    # Default fallback: empty list
    return []

