def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict containing type specifications")

        # Determine the base conversion function
        base = spec_option.get("type")
        if base is None:
            raise ValueError("spec_option must contain a 'type' key")

        # Build a concrete converter based on the declared base type
        if base == "list":
            separator = spec_option.get("separator", ",")
            subtype = spec_option.get("subtype", str)
            def converter(value):
                return [subtype(item.strip()) for item in value.split(separator)]
        elif base == "dict":
            separator = spec_option.get("separator", ",")
            kvsep = spec_option.get("kvseparator", ":")
            def converter(value):
                result = {}
                for item in value.split(separator):
                    if kvsep not in item:
                        raise ValueError(f"Invalid dict entry: {item}")
                    k, v = [x.strip() for x in item.split(kvsep, 1)]
                    result[k] = v
                return result
        elif isinstance(base, type):
            # Use the type directly
            converter = base
        else:
            raise ValueError(f"Unsupported base type specification: {base!r}")

        # Wrap the converter in a simple callable class so that callers can
        # instantiate it like a type and get an instance storing the converted value
        class ComplexType:
            def __init__(self, value):
                self.value = converter(value)

            def __repr__(self):
                return f"<{type_name} {self.value!r}>"

        # Give the class a meaningful name
        ComplexType.__name__ = type_name
        ComplexType.__qualname__ = f"{subcommand}.{type_name}"
        return ComplexType

    except Exception as exc:
        raise ValueError(
            f"Failed to create complex argument type '{type_name}' for option '{option_name}' "
            f"under subcommand '{subcommand}': {exc}"
        ) from exc

