def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Ensure the playbook exists; if a relative path is supplied, join it
    # with the plugin's playbooks directory.
    if not os.path.isabs(playbook_path):
        if hasattr(ir_plugin, "playbooks_path"):
            playbook_path = os.path.join(ir_plugin.playbooks_path, playbook_path)
        else:
            raise ValueError("playbook_path is relative but plugin does not provide a base path")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Ansible playbook not found: {playbook_path}")

    # Determine verbosity string.
    verbosity = "-v"  # default
    if verbose is not None:
        if isinstance(verbose, int) and verbose >= 0:
            verbosity = "-" + "v" * verbose
        elif isinstance(verbose, str):
            verbosity = verbose
        else:
            raise TypeError("verbose must be an int or str")

    # Build the base command.
    cmd = ["ansible-playbook"]
    if verbosity:
        cmd.append(verbosity)

    # Add inventory if provided by the workspace.
    if hasattr(ir_workspace, "inventory_path") and ir_workspace.inventory_path:
        cmd.extend(["-i", ir_workspace.inventory_path])

    # Append any user-specified ansible-playbook arguments.
    if ansible_args:
        for key, value in ansible_args.items():
            # Ensure the key starts with '--'
            if isinstance(key, str) and not key.startswith("--"):
                key = f"--{key}"
            cmd.append(key)
            # Handle boolean flags: include only if True
            if isinstance(value, bool):
                if not value:
                    # remove the flag that was just added
                    cmd.pop()
                continue
            if value is not None:
                cmd.append(str(value))

    # Append extra variables if provided.
    if extra_vars:
        ev_items = []
        for k, v in extra_vars.items():
            # Quote string values that contain spaces.
            if isinstance(v, str) and (" " in v or "=" in v):
                v = f"'{v}'"
            ev_items.append(f"{k}={v}")
        cmd.extend(["--extra-vars", " ".join(ev_items)])

    # Finally the playbook path itself.
    cmd.append(playbook_path)

    try:
        output = subprocess.check_output(
            cmd,
            stderr=subprocess.STDOUT,
            universal_newlines=True
        )
    except subprocess.CalledProcessError as exc:
        # Re-raise with a clearer message, preserving the original output.
        raise RuntimeError(
            f"Ansible playbook '{playbook_path}' exited with non-zero status "
            f"{exc.returncode}:\n{exc.output}"
        ) from exc

    return output

