    root_norm = os.path.normpath(root)
    try:
        relative = os.path.relpath(path_norm, root_norm)
    except Exception as e:
        # On Windows, ValueError may be raised if drives differ
        raise ValueError(f"Cannot strip root: '{path}' does not start with root '{root}'") from e
